@Test
void testCompleteRegister() throws ReflectiveOperationException, SecurityException {
    // set activation properties
    List<Configuration> cfgs = cfgDao.get(CONFIG_EMAIL_AT_REGISTER, CONFIG_EMAIL_VERIFICATION);
    for (Configuration c : cfgs) {
        c.setValueB(true);
        cfgDao.update(c, null);
    }
    try {
        tester.startPage(SignInPage.class);
        tester.assertRenderedPage(SignInPage.class);
        // number uid is used to prevent password validation errors
        String uid = String.valueOf(Math.abs(rnd.nextLong()));
        performRegister(uid, "warn.notverified");
        // activate
        User u = userDao.getByLogin(getLogin(uid), User.Type.USER, null);
        assertNotNull(u);
        assertFalse(u.getRights().contains(User.Right.LOGIN));
        tester.startPage(ActivatePage.class, new PageParameters().add(ActivatePage.ACTIVATION_PARAM, u.getActivatehash()));
        tester.assertRenderedPage(SignInPage.class);
        // check activated
        u = userDao.getByLogin(getLogin(uid), User.Type.USER, null);
        assertNotNull(u);
        assertNull(u.getActivatehash());
        assertTrue(u.getRights().contains(User.Right.LOGIN));
        checkLogin(getEmail(uid), userpass);
        // logout
        Locale loc = tester.getSession().getLocale();
        tester.getSession().invalidateNow();
        tester.getSession().setLocale(loc);
        // forget by 'random'
        performForget(uid);
        // reset password
        u = userDao.getByEmail(getEmail(uid));
        assertNotNull(u);
        assertNotNull(u.getResethash());
        tester.startPage(ResetPage.class, new PageParameters().add(ResetPage.RESET_PARAM, u.getResethash()));
        tester.assertRenderedPage(ResetPage.class);
        // check reset
        String passwd = "q1W@e3r4t5";
        FormTester resetTester = tester.newFormTester("resetPassword:form");
        resetTester.setValue("password", passwd);
        resetTester.setValue("confirmPassword", passwd);
        resetTester.submit("submit");
        checkErrors(0);
        tester.assertLabel("resetInfo:content", getEscapedString("332"));
    } finally {
        for (Configuration c : cfgs) {
            c.setValueB(false);
            cfgDao.update(c, null);
        }
    }
}

@Test
void testInstall() {
    InstallWizardPage page = tester.startPage(InstallWizardPage.class);
    tester.assertRenderedPage(InstallWizardPage.class);
    InstallWizard wiz = (InstallWizard) page.get(WIZARD_PATH);
    assertFalse(wiz.isEnabled(), "Wizard should be disabled");
    AjaxClientInfoBehavior clientInfo = page.getBehaviors(AjaxClientInfoBehavior.class).get(0);
    tester.executeBehavior(clientInfo);
    assertTrue(wiz.isEnabled(), "Wizard should be enabled");
    assertNotNull(wiz.getWizardModel().getActiveStep(), "Model should NOT be null");
    WizardButton prev = getWizardButton("previous");
    //check enabled, add check for other buttons on other steps
    assertFalse(prev.isEnabled(), "Prev button should be disabled");
    WizardButton next = getWizardButton("next");
    AbstractAjaxBehavior finish = (AbstractAjaxBehavior) getWizardButton("finish").getBehaviorById(0);
    FormTester wizardTester = tester.newFormTester(FORM_PATH);
    wizardTester.submit(next);
    wizardTester = tester.newFormTester(FORM_PATH);
    wizardTester.select("view:form:dbType", 1);
    checkErrors(tester, 0);
    //user step
    wizardTester.submit(next);
    checkErrors(tester, 0);
    wizardTester = tester.newFormTester(FORM_PATH);
    wizardTester.setValue("view:username", adminUsername);
    wizardTester.setValue("view:password", userpass);
    wizardTester.setValue("view:email", email);
    String[] tzIds = TimeZone.getAvailableIDs();
    wizardTester.select("view:timeZone", rnd.nextInt(tzIds.length));
    wizardTester.setValue("view:group", group);
    //cfg+smtp step
    wizardTester.submit(next);
    checkErrors(tester, 0);
    wizardTester = tester.newFormTester(FORM_PATH);
    wizardTester.setValue("view:smtpPort", "25");
    wizardTester.select("view:defaultLangId", 0);
    //converters step
    wizardTester.submit(next);
    checkErrors(tester, 0);
    wizardTester = tester.newFormTester(FORM_PATH);
    wizardTester.setValue("view:docDpi", "150");
    wizardTester.setValue("view:docQuality", "90");
    //crypt step
    wizardTester.submit(next);
    // not checking errors
    if (countErrors(tester) > 0) {
        tester.cleanupFeedbackMessages();
        wizardTester = tester.newFormTester(FORM_PATH);
        wizardTester.setValue("view:docDpi", "150");
        wizardTester.setValue("view:docQuality", "90");
        //skip errors
        wizardTester.submit(next);
    }
    wizardTester = tester.newFormTester(FORM_PATH);
    wizardTester.setValue("view:cryptClassName", SCryptImplementation.class.getName());
    //install step
    wizardTester.submit(next);
    checkErrors(tester, 0);
    tester.executeBehavior(finish);
    checkErrors(tester, 0);
}

@Test
void testTemplateGeneration() {
    Appointment a = getAppointment();
    String[] ids = TimeZone.getAvailableIDs();
    Recording rec = new Recording();
    rec.setRoomId(5L);
    List<User> users = new ArrayList<>(userDao.get(0, 100));
    User en = new User();
    // ltr
    en.setLanguageId(1L);
    User ar = new User();
    // rtl, arabic
    ar.setLanguageId(14L);
    users.add(en);
    users.add(ar);
    Group g = new Group();
    g.setName("Template test");
    for (User u : users) {
        TimeZone tz = TimeZone.getTimeZone(ids[rnd.nextInt(ids.length)]);
        checkTemplate(CreatedAppointmentTemplate.get(u, a, tz, u.getLogin()));
        checkTemplate(CanceledAppointmentTemplate.get(u, a, tz, u.getLogin()));
