@Test
void test1() throws Exception {
    final String dateStr = "19-11-29 07:05";
    final String pattern = "y-MM-dd HH:mm";
    final Locale loc = new Locale.Builder().setLanguage("sv").setRegion("SE").build();
    Date d = new SimpleDateFormat(pattern, loc).parse(dateStr);
    Calendar c = Calendar.getInstance();
    c.setTime(d);
    assertEquals(2019, c.get(Calendar.YEAR), "4 digit year expected");
    LocalDateTime dt = LocalDateTime.parse(dateStr, DateTimeFormatter.ofPattern(pattern, loc));
    assertEquals(19, dt.getYear(), "2 digit year expected");
    dt = LocalDateTime.parse(dateStr, DateTimeFormatter.ofPattern(pattern.replace("y", "yy"), loc));
    assertEquals(2019, dt.getYear(), "4 digit year expected");
}

@Test
void test2() throws Exception {
    final String dateStr = "2020-05-12, 6:43 a.m.";
    final String jsDateStr = "2020-05-12, 6:43 AM";
    final String pattern = "y-MM-dd, h:mm a";
    final Locale loc = new Locale.Builder().setLanguage("en").setRegion("CA").build();
    DateTimeFormatter formatter = new DateTimeFormatterBuilder().parseCaseInsensitive().appendPattern(pattern).toFormatter(loc);
    assertNotNull(formatter.parse(dateStr));
    DateTimeFormatter formatter1 = new DateTimeFormatterBuilder().parseCaseInsensitive().appendPattern(pattern).toFormatter(Locale.ENGLISH);
    assertNotNull(formatter1.parse(jsDateStr));
}

@Test
void test3() throws Exception {
    final Locale loc = new Locale.Builder().setLanguage("fr").setRegion("CA").build();
    final String result = Runtime.version().feature() < 17 ? // java 11
    "yy-MM-dd HH [h] mm" : // java 17
    "y-MM-dd HH [h] mm";
    String format = AbstractOmDateTimePicker.getDateTimeFormat(loc);
    assertEquals(result, AbstractOmDateTimePicker.patch(format));
    format = AbstractOmDateTimePicker.getDateTimeFormat(Locale.ENGLISH);
    assertEquals(format, AbstractOmDateTimePicker.patch(format));
}

